-- Script 108 · parte 1 de 4: cheques de la organización 3 y su detalle contable (582 cheques y 617 líneas).
--   Ejecutar las 4 partes en orden (1, 2, 3, 4) en el SQL Editor de Supabase. Es el mismo script 108 partido:
--   el resultado es igual a ejecutarlo completo, y cada parte se puede ejecutar de nuevo (solo actualiza).
-- Cheques de la organización 3 (Futura Farma - Mavisa) y su detalle contable, de los archivos «CON_CHEQUES.xls»
-- (2325 cheques: 2129 de la 3-01, 124 de la 3-02, 72 de la 3-03) y «CON_DETCON_CHEQUES_VER.xls» (2481 líneas: 2324 de la 3-01, 4 de la 3-02, 153 de la 3-03).
--   1. Si el cheque ya existe (misma cuenta bancaria y número) NO se crea: se actualiza. Igual las líneas
--      (mismo cheque y número de línea).
--   2. Columnas nuevas (vienen con datos en los archivos y no estaban en la base de datos):
--      movimientos_bancarios:
--        origen_anterior: marca MIGRADO (cheque del sistema anterior)
--        proveedor_codigo_anterior: PROVEEDOR
--        procesado: PROCESADO (S/N)
--        tipo_anterior: TIPO
--        conciliado_anterior: CONCILIADO (C = conciliado; I y A del sistema anterior)
--        fecha_anulacion_anterior: FECHA_ANULACION
--        motivo_anulacion_codigo: MOTIVO_ANULACION
--        moneda_integracion: MONEDA_INTEGRACION (1 = Q, 2 = US$)
--        valor_cambio_anterior: VALOR_CAMBIO
--        lugar: LUGAR
--        postfechado: POSTFECHADO (S/N)
--        usuario_modifica_anterior: USR_MODIFICA
--        fecha_modifica_anterior: FECHA_MODIFICA
--        transaccion_anterior: TRANSACCION (número; se liga por número en la localidad)
--        negociable_anterior: NEGOCIABLE (N = no negociable)
--        fecha_ingreso_anterior: FECHA_INGRESO
--        obviar_anticipo: OBVIAR_ANTICIPO (S/N)
--        observaciones_anulacion: OBSERVACIONES_ANULACION
--        valor_mi: VALOR_MI
--        tipo_rubro: TIPO_RUBRO
--        documento_mig: DOCUMENTO_MIG
--        valor_anterior: VALOR tal como venía (en quetzales)
--        cuenta_bancaria_anterior: CUENTA_BANCARIA tal como venía
--      movimiento_lineas:
--        debe_mi: DEBITO_MI
--        haber_mi: CREDITO_MI
--        cuenta_codigo_anterior: CUENTA
--        version_cuenta_anterior: VERSION
--        tipo_int_centro: TIPO_INT_CENTRO
--      Columnas vacías en todas las filas (no se agregan): FECHA_ENTREGA, ORDEN_COMPRA, PROVISION, SOLICITUD_CHEQUE, AÑO_SOLICITUD, MES_SOLICITUD, TIPO_NOMINA, NOMINA, AÑO_POLIZA, MES_POLIZA, POLIZA, CREDITO, PERSONA_BENEFICIO, TIPO_TRANSACCION, DEPARTAMENTO, CHEQUE_IMPRESO, RECIBO_PAGO, CHEQUE_INICIAL, CHEQUE_FINAL, MI_VALOR, DOCUMENTO, USUARIO_ANULA, FECHA_COBRO, AÑO_ANULACION, MES_ANULACION, POLIZA_ANULACION, FECHA_FIRMA, RECIBE_CHEQUE, CIERRE, EMPLEADO, CODIGO_BANCO, RUBRO_FE, AÑO_FL, MES_FL, SEMANA, RUBRO, LINEA, SEMANA_RUBRO, AÑO_RUBRO; del detalle: CENTRO_COSTO.
--   Equivalencias: ESTADO V/A = ACTIVO/ANULADO; VALOR viene en quetzales: los cheques en dólares (MONEDA_INTEGRACION
--   2) van en US$ (VALOR_MI) con su valor de cambio; los demás en quetzales (cambio 1; VALOR_CAMBIO y VALOR_MI quedan
--   como dato). CONCILIADO C = conciliado. NEGOCIABLE N = no negociable. CXC, FIRMADO S/N. La cuenta bancaria se liga
--   por su número en la localidad (sin el punto final que traen algunas de 3-03); el proveedor por su código y la
--   transacción por su número. Las cuentas del detalle se buscan en el catálogo de la versión indicada (VERSION = 1) de la localidad y, si ahí no
--   existen, en su otra versión activa (algunas cuentas solo están en la versión 2).
--   El número de cheque se conserva tal como viene (también los negativos del sistema anterior). Los cheques
--   anulados pueden tener valor 0. No se carga el cheque 0 de valor 0 a favor de «X» (1): es un marcador.
--   Folio: los cheques nuevos reciben el siguiente folio de su localidad (por fecha); los existentes conservan el suyo.
--   Los cheques se ligan a las compras que liquidaron (compra_documentos_banco, script 94). El saldo de las compras
--   sigue saliendo de los documentos de liquidación (script 107): no se cuenta dos veces.
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.
-- Se ejecuta después del script 107.

alter table public.movimientos_bancarios add column if not exists origen_anterior text;
alter table public.movimientos_bancarios add column if not exists proveedor_codigo_anterior integer;
alter table public.movimientos_bancarios add column if not exists procesado boolean;
alter table public.movimientos_bancarios add column if not exists tipo_anterior text;
alter table public.movimientos_bancarios add column if not exists conciliado_anterior text;
alter table public.movimientos_bancarios add column if not exists fecha_anulacion_anterior date;
alter table public.movimientos_bancarios add column if not exists motivo_anulacion_codigo integer;
alter table public.movimientos_bancarios add column if not exists moneda_integracion integer;
alter table public.movimientos_bancarios add column if not exists valor_cambio_anterior numeric(18, 6);
alter table public.movimientos_bancarios add column if not exists lugar text;
alter table public.movimientos_bancarios add column if not exists postfechado boolean;
alter table public.movimientos_bancarios add column if not exists usuario_modifica_anterior text;
alter table public.movimientos_bancarios add column if not exists fecha_modifica_anterior timestamp;
alter table public.movimientos_bancarios add column if not exists transaccion_anterior integer;
alter table public.movimientos_bancarios add column if not exists negociable_anterior text;
alter table public.movimientos_bancarios add column if not exists fecha_ingreso_anterior timestamp;
alter table public.movimientos_bancarios add column if not exists obviar_anticipo boolean;
alter table public.movimientos_bancarios add column if not exists observaciones_anulacion text;
alter table public.movimientos_bancarios add column if not exists valor_mi numeric(18, 2);
alter table public.movimientos_bancarios add column if not exists tipo_rubro text;
alter table public.movimientos_bancarios add column if not exists documento_mig text;
alter table public.movimientos_bancarios add column if not exists valor_anterior numeric(18, 2);
alter table public.movimientos_bancarios add column if not exists cuenta_bancaria_anterior text;
alter table public.movimiento_lineas add column if not exists debe_mi numeric(18, 2);
alter table public.movimiento_lineas add column if not exists haber_mi numeric(18, 2);
alter table public.movimiento_lineas add column if not exists cuenta_codigo_anterior text;
alter table public.movimiento_lineas add column if not exists version_cuenta_anterior integer;
alter table public.movimiento_lineas add column if not exists tipo_int_centro text;
alter table public.movimientos_bancarios drop constraint if exists movimientos_bancarios_valor_check;
alter table public.movimientos_bancarios add constraint movimientos_bancarios_valor_check check (valor > 0 or (estado = 'ANULADO' and valor >= 0));

do $migra$
declare
  v_org bigint; v_gtq bigint; v_usd bigint;
  r record; v_loc bigint; v_cb record; v_id bigint; v_folio integer; v_prov text; v_tr bigint; v_cta bigint;
  v_nuevo boolean;
  v_faltan text[] := '{}';
  c_n int := 0; c_a int := 0; c_s int := 0; l_n int := 0; l_a int := 0; l_s int := 0; l_c int := 0; v_lig int;
begin
  select id into v_org from public.organizaciones where codigo = '3';
  if v_org is null then raise notice 'No existe la organización 3.'; return; end if;
  select id into v_gtq from public.monedas where iso = 'GTQ';
  select id into v_usd from public.monedas where iso = 'USD';
  -- La carga trae folio, número, estado y usuario del sistema anterior: se suspenden los automatismos de la pantalla.
  alter table public.movimientos_bancarios disable trigger movimientos_bancarios_preparar;
  alter table public.movimientos_bancarios disable trigger movimientos_bancarios_cheque;
  alter table public.movimientos_bancarios disable trigger movimientos_bancarios_solicitud;
  alter table public.movimientos_bancarios disable trigger movimientos_bancarios_marcar_solicitud;
  alter table public.movimiento_lineas disable trigger movimiento_lineas_validar;

