    (1, '3659016341', '945', '2018-04-06', 4000, 'GTQ', 1, 'RODELBI FUENTES***** ANULADO****', null, 'ANULADO', null, null, null, false, 'M', 'I', null, null, null, 1, 1, 'GUATEMALA', null, null, null, 1021, 'N', '2018-04-06 00:00:00', false, false, null, null, null, '000000000945', false, 4000, '3659016341'),
    (1, '3659016341', '946', '2018-04-06', 4000, 'GTQ', 1, 'RODELBI FUENTES', 'CONTABILIDAD JUN-DIC 2017, CIERRE 2017, CONTA OM Y SZ.', 'ACTIVO', null, null, null, false, 'M', 'I', null, null, null, 1, 1, 'GUATEMALA', null, null, null, 1021, 'N', '2018-04-06 00:00:00', false, false, null, null, null, '000000000946', false, 4000, '3659016341'),
    (1, '3659016341', '947', '2018-04-06', 1015, 'GTQ', 1, 'TELGUA', 'TELEFONO 2508-4372, 24326009,5516-2921', 'ACTIVO', null, null, null, false, 'M', 'I', null, null, null, 1, 1, 'GUATEMALA', null, null, null, 1021, 'N', '2018-04-06 00:00:00', false, false, null, null, null, '000000000947', false, 1015, '3659016341')) as x(loc, cuenta, numero, fecha, valor, moneda, cambio, beneficiario, descripcion, estado, usuario, f_anula, proveedor, procesado, tipo_ant,
      conciliado, f_concilia, motivo_cod, motivo, moneda_int, cambio_ant, lugar, postfechado, usr_mod, f_mod, transaccion, negociable, f_ingreso, firmado,
      obviar, obs_anula, valor_mi, tipo_rubro, doc_mig, cxc, valor_ant, cuenta_ant)
    order by loc, fecha, numero loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select cb.id, cb.moneda_id into v_cb from public.cuentas_bancarias cb where cb.localidad_id = v_loc and cb.numero = r.cuenta;
    if v_cb.id is null then c_s := c_s + 1; raise notice 'Cheque % (3-0%): no existe la cuenta bancaria %.', r.numero, r.loc, r.cuenta; continue; end if;
    select id into v_id from public.movimientos_bancarios where tipo = 'CHEQUE' and cuenta_bancaria_id = v_cb.id and numero_documento = r.numero;
    select nombre_comercial into v_prov from public.proveedores where localidad_id = v_loc and codigo = r.proveedor::integer;
    select id into v_tr from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer;
    if v_id is null then
      select coalesce(max(folio), 0) + 1 into v_folio from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'CHEQUE';
      insert into public.movimientos_bancarios (organizacion_id, localidad_id, cuenta_bancaria_id, tipo, folio, numero_documento, fecha, moneda_id, tipo_cambio,
        valor, valor_ml, valor_cuenta, descripcion, tipo_tercero, tercero_codigo, tercero_nombre, estado, anulado_por, anulado_en, motivo_anulacion, usuario,
        fecha_operacion, transaccion_id, conciliado, fecha_conciliado, deposito_por, no_negociable, cxc, firmado)
      values (v_org, v_loc, v_cb.id, 'CHEQUE', v_folio, r.numero, r.fecha::date, case when r.moneda = 'USD' then v_usd else v_gtq end, r.cambio,
        r.valor, round(r.valor * r.cambio, 2), case when (case when r.moneda = 'USD' then v_usd else v_gtq end) = v_cb.moneda_id then r.valor else round(r.valor * r.cambio, 2) end,
        nullif(trim(r.descripcion::text), ''), case when r.proveedor is not null then 'PROVEEDOR PRODUCTOS' end, r.proveedor::text, v_prov, r.estado,
        case when r.estado = 'ANULADO' then coalesce(r.usuario::text, 'SISTEMA ANTERIOR') end, case when r.estado = 'ANULADO' then coalesce(r.f_anula::date, r.fecha::date)::timestamptz end,
        case when r.estado = 'ANULADO' then coalesce(r.motivo::text || coalesce(' · ' || r.obs_anula::text, ''), r.obs_anula::text, 'Anulado en el sistema anterior') end,
        coalesce(upper(r.usuario::text), 'SISTEMA ANTERIOR'), coalesce(r.f_ingreso::timestamp, r.fecha::timestamp)::timestamptz, v_tr, upper(coalesce(r.conciliado::text, '')) = 'C', r.f_concilia::date,
        nullif(upper(trim(r.beneficiario::text)), ''), upper(coalesce(r.negociable::text, '')) = 'N', coalesce(r.cxc::boolean, false), coalesce(r.firmado::boolean, false))
      returning id into v_id;
      c_n := c_n + 1;
    else
      update public.movimientos_bancarios set fecha = r.fecha::date, valor = r.valor, tipo_cambio = r.cambio,
        moneda_id = case when r.moneda = 'USD' then v_usd else v_gtq end, valor_ml = round(r.valor * r.cambio, 2),
        valor_cuenta = case when (case when r.moneda = 'USD' then v_usd else v_gtq end) = v_cb.moneda_id then r.valor else round(r.valor * r.cambio, 2) end,
        descripcion = nullif(trim(r.descripcion::text), ''), tercero_codigo = r.proveedor::text, tercero_nombre = v_prov,
