        conciliado = upper(coalesce(r.conciliado::text, '')) = 'C', fecha_conciliado = r.f_concilia::date, transaccion_id = coalesce(v_tr, transaccion_id),
        deposito_por = nullif(upper(trim(r.beneficiario::text)), ''), no_negociable = upper(coalesce(r.negociable::text, '')) = 'N',
        cxc = coalesce(r.cxc::boolean, false), firmado = coalesce(r.firmado::boolean, false)
      where id = v_id;
