    (1, '3659016341', '918', 1, '1010102001', 1, 0, 24389.9, null, null, null, 'I'),
    (1, '3659016341', '919', 1, '1010102001', 1, 0, 1200, null, null, null, 'I'),
    (1, '3659016341', '920', 1, '1010102001', 1, 0, 4000, null, null, null, 'I'),
    (1, '3659016341', '921', 1, '1010102001', 1, 0, 1750, null, null, null, 'I'),
    (1, '3659016341', '922', 1, '1010102001', 1, 0, 1120, null, null, null, 'I'),
    (1, '3659016341', '923', 1, '1010102001', 1, 0, 231, null, null, null, 'I'),
    (1, '3659016341', '924', 1, '1010102001', 1, 0, 778, null, null, null, 'I'),
    (1, '3659016341', '925', 1, '1010102001', 1, 0, 4206.25, null, null, null, 'I'),
    (1, '3659016341', '926', 1, '1010102001', 1, 0, 938.1, null, null, null, 'I'),
    (1, '3659016341', '927', 1, '1010102001', 1, 0, 1000, null, null, null, 'I'),
    (1, '3659016341', '928', 1, '1010102001', 1, 0, 35512.85, null, null, null, 'I'),
    (1, '3659016341', '929', 1, '1010102001', 1, 0, 1015, null, null, null, 'I'),
    (1, '3659016341', '930', 1, '1010102001', 1, 0, 1250, null, null, null, 'I'),
    (1, '3659016341', '931', 1, '1010102001', 1, 0, 4000, null, null, null, 'I'),
    (1, '3659016341', '932', 1, '1010102001', 1, 0, 2000, null, null, null, 'I'),
    (1, '3659016341', '933', 1, '1010102001', 1, 0, 1500, null, null, null, 'I'),
    (1, '3659016341', '934', 1, '1010102001', 1, 0, 50000, null, null, null, 'I'),
    (1, '3659016341', '935', 1, '1010102001', 1, 0, 1200, null, null, null, 'I'),
    (1, '3659016341', '936', 1, '1010102001', 1, 0, 49286.38, null, null, null, 'I'),
    (1, '3659016341', '937', 1, '1010102001', 1, 0, 1200, null, null, null, 'I'),
    (1, '3659016341', '938', 1, '1010102001', 1, 0, 4000, null, null, null, 'I'),
    (1, '3659016341', '939', 1, '1010102001', 1, 0, 1750, null, null, null, 'I'),
    (1, '3659016341', '940', 1, '1010102001', 1, 0, 4500, null, null, null, 'I'),
    (1, '3659016341', '941', 1, '1010102001', 1, 0, 3000, null, null, null, 'I'),
    (1, '3659016341', '942', 1, '1010102001', 1, 0, 3000, null, null, null, 'I'),
    (1, '3659016341', '943', 1, '1010102001', 1, 0, 1050, null, null, null, 'I'),
    (1, '3659016341', '944', 1, '1010102001', 1, 0, 2800, null, null, null, 'I'),
    (1, '3659016341', '946', 1, '1010102001', 1, 0, 4000, null, null, null, 'I'),
    (1, '3659016341', '947', 1, '1010102001', 1, 0, 1015, null, null, null, 'I')) as x(loc, cuenta, numero, linea, codigo, version, debe, haber, debe_mi, haber_mi, centro, tipo_centro) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select m.id into v_id from public.movimientos_bancarios m join public.cuentas_bancarias cb on cb.id = m.cuenta_bancaria_id
    where m.tipo = 'CHEQUE' and cb.localidad_id = v_loc and cb.numero = r.cuenta and m.numero_documento = r.numero;
    if v_id is null then l_s := l_s + 1; continue; end if;
    select k.id into v_cta from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
    where g.localidad_id = v_loc and k.codigo = r.codigo order by (g.version = r.version) desc, g.activo desc, g.version desc limit 1;
    if v_cta is null then l_c := l_c + 1; v_faltan := array_append(v_faltan, format('3-0%s %s', r.loc, r.codigo)); continue; end if;
    insert into public.movimiento_lineas (movimiento_id, linea, cuenta_id, debe, haber, debe_mi, haber_mi, cuenta_codigo_anterior, version_cuenta_anterior, tipo_int_centro)
    values (v_id, r.linea, v_cta, r.debe, r.haber, r.debe_mi::numeric, r.haber_mi::numeric, r.codigo, r.version, r.tipo_centro::text)
    on conflict (movimiento_id, linea) do update set cuenta_id = excluded.cuenta_id, debe = excluded.debe, haber = excluded.haber, debe_mi = excluded.debe_mi,
      haber_mi = excluded.haber_mi, cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      tipo_int_centro = excluded.tipo_int_centro
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then l_n := l_n + 1; else l_a := l_a + 1; end if;
  end loop;

  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_preparar;
  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_cheque;
  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_solicitud;
  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_marcar_solicitud;
  alter table public.movimiento_lineas enable trigger movimiento_lineas_validar;

  -- Cheques con que se liquidaron las compras (script 94): se ligan al cheque migrado.
  update public.compra_documentos_banco d set movimiento_id = m.id
  from public.compras c, public.movimientos_bancarios m
  where c.id = d.compra_id and c.organizacion_id = v_org and d.tipo = 'CHEQUE' and m.tipo = 'CHEQUE'
    and m.cuenta_bancaria_id = d.cuenta_bancaria_id and m.numero_documento = d.numero::text and d.movimiento_id is distinct from m.id;
  get diagnostics v_lig = row_count;

  raise notice '%', format('Cheques: %s nuevos, %s actualizados, %s sin cuenta bancaria. Detalle contable: %s líneas nuevas, %s actualizadas, %s sin cheque, %s sin cuenta. Documentos de compras ligados a su cheque: %s.',
    c_n, c_a, c_s, l_n, l_a, l_s, l_c, v_lig);
  if l_c > 0 then raise notice 'Cuentas que no existen en el catálogo de la localidad (líneas omitidas): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

notify pgrst, 'reload schema';
